<script setup>
import { ref, onMounted } from 'vue'
import api from '@/api/client'
import RetentionPanel from '@/components/provider/RetentionPanel.vue'
const loading=ref(true), error=ref(''), search=ref(''), summary=ref({}), customers=ref([]), selected=ref(null), detailLoading=ref(false), birthdayInput=ref(''), savingBirthday=ref(false)
async function load(){loading.value=true;error.value='';try{const {data}=await api.get('/provider/crm/customers',{params:{search:search.value||undefined}});summary.value=data.summary||{};customers.value=data.customers?.data||[]}catch(e){error.value=e.response?.data?.message||'Could not load CRM data.'}finally{loading.value=false}}
async function openCustomer(c){detailLoading.value=true;selected.value={customer:c,metrics:{},appointments:[],sales:[]};birthdayInput.value=c.birthday?String(c.birthday).slice(0,10):'';try{const {data}=await api.get('/provider/crm/customers/'+c.id);selected.value=data;birthdayInput.value=data.customer?.birthday?String(data.customer.birthday).slice(0,10):''}catch(e){error.value=e.response?.data?.message||'Unable to load customer profile.'}finally{detailLoading.value=false}}\nasync function saveBirthday(){if(!selected.value?.customer)return;savingBirthday.value=true;try{const {data}=await api.patch('/provider/crm/customers/'+selected.value.customer.id+'/birthday',{birthday:birthdayInput.value||null});selected.value.customer=data.customer;await load()}catch(e){error.value=e.response?.data?.message||'Unable to save birthday.'}finally{savingBirthday.value=false}}
function money(v){return new Intl.NumberFormat('en-KE',{style:'currency',currency:'KES',maximumFractionDigits:0}).format(Number(v||0))}
function segment(s){return ({vip:'VIP',active:'Active',inactive:'Inactive',new:'New'})[s]||s}
onMounted(load)
</script>
<template><main class="mx-auto max-w-7xl space-y-6 py-6 sm:py-10"><header class="rounded-3xl bg-ink p-7 text-white sm:p-10"><p class="text-xs font-semibold uppercase tracking-widest text-clay-300">Customer relationship management</p><h1 class="mt-2 font-heading text-3xl font-bold sm:text-4xl">Customer CRM</h1><p class="mt-3 max-w-xl text-white/70">Understand your clients, identify loyal customers and reconnect with customers who have not visited recently.</p></header>
<RetentionPanel />
<section class="grid gap-3 sm:grid-cols-3"><article class="rounded-2xl border bg-white p-5"><p class="text-sm text-ink-soft">Customers</p><p class="mt-1 text-3xl font-bold">{{summary.customers??'—'}}</p></article><article class="rounded-2xl border bg-white p-5"><p class="text-sm text-ink-soft">VIP (KES 50,000+ net spend)</p><p class="mt-1 text-3xl font-bold">{{summary.vip??'—'}}</p></article><article class="rounded-2xl border bg-white p-5"><p class="text-sm text-ink-soft">Inactive (90 days)</p><p class="mt-1 text-3xl font-bold">{{summary.inactive_90_days??'—'}}</p></article></section>
<section class="rounded-2xl border bg-white p-4 sm:p-6"><div class="mb-4 flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><h2 class="text-xl font-semibold">Customer directory</h2><div class="flex gap-2"><input v-model="search" @keyup.enter="load" placeholder="Search name, phone or email" class="min-w-0 flex-1 rounded-xl border px-3 py-2 sm:w-72"/><button @click="load" class="rounded-xl bg-ink px-4 py-2 text-white">Search</button></div></div><p v-if="error" class="mb-3 rounded-lg bg-red-50 p-3 text-red-700">{{error}}</p><p v-if="loading" class="py-8 text-center">Loading CRM…</p><p v-else-if="!customers.length" class="py-8 text-center text-ink-soft">No customers found.</p><div v-else class="overflow-x-auto"><table class="w-full min-w-[650px] text-left text-sm"><thead><tr class="border-b text-ink-soft"><th class="p-3">Customer</th><th class="p-3">Visits</th><th class="p-3">Spend</th><th class="p-3">Last visit</th><th class="p-3">Segment</th><th></th></tr></thead><tbody><tr v-for="c in customers" :key="c.id" class="border-b last:border-0 hover:bg-paper/50"><td class="p-3"><div class="font-medium">{{c.name}}</div><div class="text-xs text-ink-soft">{{c.phone||c.email||'No contact'}}</div></td><td class="p-3">{{c.completed_visits||0}}</td><td class="p-3">{{money(c.lifetime_spend)}}</td><td class="p-3">{{c.last_visit_at?new Date(c.last_visit_at).toLocaleDateString():'—'}}</td><td class="p-3"><span class="rounded-full bg-clay-100 px-2.5 py-1 text-xs font-medium">{{segment(c.segment)}}</span></td><td class="p-3"><button @click="openCustomer(c)" class="font-semibold text-clay-700 hover:underline">View</button></td></tr></tbody></table></div></section>
<div v-if="selected" class="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-3" @click.self="selected=null"><section class="max-h-[90vh] w-full max-w-3xl overflow-y-auto rounded-2xl bg-white p-5 sm:p-7"><div class="flex items-start justify-between"><div><h2 class="text-2xl font-bold">{{selected.customer?.name}}</h2><p class="text-sm text-ink-soft">{{selected.customer?.phone}} · {{selected.customer?.email}}</p></div><button class="rounded-lg border px-3 py-1" @click="selected=null">Close</button></div><div class="my-4 flex flex-wrap items-end gap-2"><label class="text-sm">Birthday<input v-model="birthdayInput" type="date" class="ml-2 rounded-lg border px-2 py-1"/></label><button @click="saveBirthday" :disabled="savingBirthday" class="rounded-lg bg-ink px-3 py-2 text-sm text-white">{{savingBirthday?'Saving…':'Save birthday'}}</button></div><p v-if="detailLoading" class="py-6">Loading profile…</p><div v-else><div class="mt-5 grid grid-cols-2 gap-3 sm:grid-cols-4"><div class="rounded-xl bg-paper p-3"><p class="text-xs text-ink-soft">Visits</p><p class="text-xl font-bold">{{selected.metrics?.completed_visits}}</p></div><div class="rounded-xl bg-paper p-3"><p class="text-xs text-ink-soft">Lifetime spend</p><p class="text-xl font-bold">{{money(selected.metrics?.lifetime_spend)}}</p></div><div class="rounded-xl bg-paper p-3"><p class="text-xs text-ink-soft">Cancelled</p><p class="text-xl font-bold">{{selected.metrics?.cancelled_visits}}</p></div><div class="rounded-xl bg-paper p-3"><p class="text-xs text-ink-soft">Last visit</p><p class="text-sm font-semibold">{{selected.metrics?.last_visit_at?new Date(selected.metrics.last_visit_at).toLocaleDateString():'—'}}</p></div></div><h3 class="mt-6 font-semibold">Recent appointments</h3><div v-if="!selected.appointments?.length" class="py-3 text-sm text-ink-soft">No appointment history.</div><ul class="divide-y"><li v-for="a in selected.appointments" :key="a.id" class="flex justify-between gap-3 py-2 text-sm"><span>{{a.service?.name||a.services?.map(s=>s.name).join(', ')||'Appointment'}} · {{new Date(a.scheduled_at).toLocaleString()}}</span><span class="capitalize">{{a.status}}</span></li></ul><h3 class="mt-6 font-semibold">Recent POS sales</h3><div v-if="!selected.sales?.length" class="py-3 text-sm text-ink-soft">No POS sales history.</div><ul class="divide-y"><li v-for="s in selected.sales" :key="s.id" class="flex justify-between gap-3 py-2 text-sm"><span>{{s.receipt_number}} · {{new Date(s.created_at).toLocaleDateString()}}</span><span class="font-semibold">{{money(s.paid_amount)}}</span></li></ul></div></section></div></main></template>